    if (redirect_info->new_url.SchemeIsHTTPOrHTTPS()) {
      if (headers_update_params) {
        headers_update_params->SetHeader("X-Candidate-Canary", candidate_id_);
      }
    }
  }

 private:
  std::string candidate_id_;
};

